//! The DOCX writer (SP2a Task 9). Trust core: it places each cited claim in a `kw-claim-<n>`
//! bookmark (`n` the claim's final ordinal), follows it with its source numbers, and lists the
//! sources at the end, all generated by code. From a citation it takes only the id and the
//! `display`: never `exact` or the source ref, which hold hidden text whole.
use std::{collections::HashMap, io::Cursor};

use docx_rs::{
    AbstractNumbering, Docx, IndentLevel, Level, LevelJc, LevelOverride, LevelText, NumberFormat,
    Numbering, NumberingId, Paragraph, Run, RunFonts, Start, Style, StyleType, Table, TableCell,
    TableRow, VertAlignType,
};

use super::{
    DocError, Rendered,
    content::{
        ClaimInline, ClaimSpec, ContentBlock, DocContent, Inline, PlacedClaim, WrittenContent,
        cited_ordinals, clean_text, uncited_claims,
    },
    deadline,
};
use crate::{evidence::citation::CitationRow, ids::CitationId};

/// The font of every run: Sarabun for ASCII, high-ANSI, East Asian and complex script.
const FONT: &str = "Sarabun";
/// 16 pt, in half-points.
const BODY_SIZE: usize = 32;
/// The sources section's heading.
pub const SOURCES_HEADING: &str = "Sources · แหล่งที่มา";
const ORDERED: usize = 1;
const BULLETED: usize = 2;

/// The bookmark name of the claim with ordinal `n`.
pub fn bookmark_name(n: u32) -> String {
    format!("kw-claim-{n}")
}

/// Source numbers by first use, and the citations they stand for.
pub(crate) struct Sources<'a> {
    numbers: HashMap<CitationId, usize>,
    order: Vec<&'a CitationRow>,
}

impl<'a> Sources<'a> {
    /// Numbers every citation the claims name, by first use; a claim naming a citation not
    /// in `rows` is `Internal` (the tool loaded every one before rendering).
    pub(crate) fn new<'c>(
        claims: impl IntoIterator<Item = &'c ClaimSpec>,
        rows: &'a [CitationRow],
    ) -> Result<Self, DocError> {
        let by_id: HashMap<CitationId, &CitationRow> = rows.iter().map(|r| (r.id, r)).collect();
        let mut sources = Sources {
            numbers: HashMap::new(),
            order: Vec::new(),
        };
        for claim in claims {
            for id in &claim.cite {
                if sources.numbers.contains_key(id) {
                    continue;
                }
                let row = by_id.get(id).ok_or(DocError::Internal)?;
                sources.order.push(row);
                sources.numbers.insert(*id, sources.order.len());
            }
        }
        Ok(sources)
    }

    /// `[1,3]`: the claim's source numbers, in its cite order.
    fn marker(&self, claim: &ClaimSpec) -> String {
        let numbers: Vec<String> = claim
            .cite
            .iter()
            .map(|id| self.numbers[id].to_string())
            .collect();
        format!("[{}]", numbers.join(","))
    }

    /// The display of each source, in source-number order: the only text taken from a citation.
    pub(crate) fn displays(&self) -> impl Iterator<Item = String> + '_ {
        self.order.iter().map(|row| clean_text(&row.display))
    }

    pub(crate) fn displays_of<'c>(
        &'c self,
        claim: &'c ClaimSpec,
    ) -> impl Iterator<Item = String> + 'c {
        claim
            .cite
            .iter()
            .map(|id| clean_text(&self.order[self.numbers[id] - 1].display))
    }
}

struct Writer<'a> {
    sources: Sources<'a>,
    ordinals: std::vec::IntoIter<u32>,
    claims: Vec<PlacedClaim>,
    next_numbering: usize,
    docx: Docx,
}

impl Writer<'_> {
    fn paragraph(
        &mut self,
        mut paragraph: Paragraph,
        inlines: &[Inline],
    ) -> Result<Paragraph, DocError> {
        for inline in inlines {
            match inline {
                Inline::Text(text) if text.is_empty() => {}
                Inline::Text(text) => paragraph = paragraph.add_run(Run::new().add_text(text)),
                Inline::Claim(ClaimInline { claim }) => {
                    let ordinal = self.ordinals.next().ok_or(DocError::Internal)?;
                    let id = ordinal as usize;
                    let mut marker = Run::new().add_text(self.sources.marker(claim));
                    marker.run_property =
                        marker.run_property.vert_align(VertAlignType::SuperScript);
                    paragraph = paragraph
                        .add_bookmark_start(id, bookmark_name(ordinal))
                        .add_run(Run::new().add_text(&claim.text))
                        .add_bookmark_end(id)
                        .add_run(marker);
                    self.claims.push(PlacedClaim {
                        ordinal,
                        kind: claim.kind,
                        text: claim.text.clone(),
                        location: format!("bookmark:{}", bookmark_name(ordinal)),
                        cite: claim.cite.clone(),
                        derive: claim.derive.clone(),
                        cited: true,
                    });
                }
            }
        }
        Ok(paragraph)
    }

    fn block(&mut self, block: &ContentBlock) -> Result<(), DocError> {
        match block {
            ContentBlock::Heading { level, text } => {
                let p = self.paragraph(Paragraph::new().style(&format!("Heading{level}")), text)?;
                self.add(p);
            }
            ContentBlock::Paragraph { text } => {
                let p = self.paragraph(Paragraph::new(), text)?;
                self.add(p);
            }
            ContentBlock::List { ordered, items } => {
                if items.is_empty() {
                    return Ok(());
                }
                // Each list is a numbering instance of its own, so an ordered list restarts at 1.
                self.next_numbering += 1;
                let id = self.next_numbering;
                let abstract_id = if *ordered { ORDERED } else { BULLETED };
                self.docx = std::mem::take(&mut self.docx).add_numbering(
                    Numbering::new(id, abstract_id).add_override(LevelOverride::new(0).start(1)),
                );
                for item in items {
                    deadline::check()?;
                    let p = Paragraph::new().numbering(NumberingId::new(id), IndentLevel::new(0));
                    let p = self.paragraph(p, item)?;
                    self.add(p);
                }
            }
            ContentBlock::Table { header, rows } => {
                let width = std::iter::once(header.len())
                    .chain(rows.iter().map(Vec::len))
                    .max()
                    .unwrap_or(0);
                if width == 0 {
                    return Ok(());
                }
                let mut table_rows = Vec::new();
                for (index, row) in std::iter::once(header).chain(rows).enumerate() {
                    if index == 0 && header.is_empty() {
                        continue;
                    }
                    let mut cells = Vec::with_capacity(width);
                    for col in 0..width {
                        deadline::check()?;
                        let inlines = row.get(col).map_or(&[][..], Vec::as_slice);
                        let mut p = Paragraph::new();
                        if index == 0 {
                            p = p.bold();
                        }
                        let p = self.paragraph(p, inlines)?;
                        cells.push(TableCell::new().add_paragraph(p));
                    }
                    table_rows.push(TableRow::new(cells));
                }
                self.docx = std::mem::take(&mut self.docx).add_table(Table::new(table_rows));
            }
        }
        Ok(())
    }

    fn add(&mut self, p: Paragraph) {
        self.docx = std::mem::take(&mut self.docx).add_paragraph(p);
    }
}

/// The document's styles and the two list definitions.
fn base() -> Docx {
    let fonts = RunFonts::new()
        .ascii(FONT)
        .hi_ansi(FONT)
        .east_asia(FONT)
        .cs(FONT);
    let level = |format: &str, text: &str| {
        Level::new(
            0,
            Start::new(1),
            NumberFormat::new(format),
            LevelText::new(text),
            LevelJc::new("left"),
        )
        .indent(
            Some(720),
            Some(docx_rs::SpecialIndentType::Hanging(360)),
            None,
            None,
        )
    };
    Docx::new()
        .default_fonts(fonts)
        .default_size(BODY_SIZE)
        .add_style(
            Style::new("Title", StyleType::Paragraph)
                .name("Title")
                .size(56)
                .bold(),
        )
        .add_style(
            Style::new("Heading1", StyleType::Paragraph)
                .name("heading 1")
                .size(44)
                .bold(),
        )
        .add_style(
            Style::new("Heading2", StyleType::Paragraph)
                .name("heading 2")
                .size(40)
                .bold(),
        )
        .add_style(
            Style::new("Heading3", StyleType::Paragraph)
                .name("heading 3")
                .size(36)
                .bold(),
        )
        .add_abstract_numbering(AbstractNumbering::new(ORDERED).add_level(level("decimal", "%1.")))
        .add_abstract_numbering(AbstractNumbering::new(BULLETED).add_level(level("bullet", "•")))
}

/// Adds `w:lang` to the document defaults: Latin text en-US, complex script th-TH, so Word
/// applies Thai rules to Thai runs. docx-rs has no setter for it.
fn with_lang(styles: Vec<u8>) -> Result<Vec<u8>, DocError> {
    let styles = String::from_utf8(styles).map_err(|_| DocError::Internal)?;
    let end = "</w:rPr></w:rPrDefault>";
    if styles.matches(end).count() != 1 {
        return Err(DocError::Internal);
    }
    Ok(styles
        .replacen(
            end,
            &format!("<w:lang w:val=\"en-US\" w:bidi=\"th-TH\" />{end}"),
            1,
        )
        .into_bytes())
}

/// Renders `content` as a DOCX: a title, headings 1 to 3, paragraphs, numbered and bulleted
/// lists and tables, each claim in its bookmark and followed by its source numbers, then the
/// sources section. Checks the pool's deadline between blocks, items and cells.
pub fn render_docx(content: &DocContent, sources: &[CitationRow]) -> Result<Rendered, DocError> {
    let written = WrittenContent::Doc(content.clone());
    let specs = super::content::claim_specs(&written);
    let uncited = uncited_claims(&written).map_err(|_| DocError::TooComplex("text"))?;
    let ordinals = cited_ordinals(specs.len(), &uncited);
    let mut writer = Writer {
        sources: Sources::new(specs.iter().copied(), sources)?,
        ordinals: ordinals.into_iter(),
        claims: Vec::with_capacity(specs.len()),
        next_numbering: 0,
        docx: base(),
    };
    if let Some(title) = &content.title {
        writer.add(
            Paragraph::new()
                .style("Title")
                .add_run(Run::new().add_text(title)),
        );
    }
    for block in &content.blocks {
        deadline::check()?;
        writer.block(block)?;
    }
    let displays: Vec<String> = writer.sources.displays().collect();
    if !displays.is_empty() {
        writer.add(
            Paragraph::new()
                .style("Heading1")
                .add_run(Run::new().add_text(SOURCES_HEADING)),
        );
        for (k, display) in displays.iter().enumerate() {
            deadline::check()?;
            writer.add(
                Paragraph::new().add_run(Run::new().add_text(format!("[{}] {display}", k + 1))),
            );
        }
    }
    let mut xml = writer.docx.build();
    xml.styles = with_lang(xml.styles)?;
    let mut bytes = Cursor::new(Vec::new());
    xml.pack(&mut bytes).map_err(|_| DocError::Internal)?;
    Ok(Rendered {
        bytes: bytes.into_inner(),
        claims: writer.claims,
    })
}
